from datetime import date


_PREFERRED_CHANNELS = {
    "": "email",
    "E": "email",
    "P": "phone",
    "M": "mail",
}


def _convert_date(value: str) -> str | None:
    if value == "" or value == "00000000":
        return None

    if len(value) != 8 or not value.isdigit():
        raise ValueError(f"Invalid legacy date: {value!r}")

    converted = date(int(value[:4]), int(value[4:6]), int(value[6:8]))
    return converted.isoformat()


def convert_contact(row: dict) -> dict | None:
    """Convert one legacy contact row, excluding soft-deleted records."""
    if row.get("DEL_FLG", "") == "Y":
        return None

    preferred_channel = row.get("PREF_CH", "")
    if preferred_channel not in _PREFERRED_CHANNELS:
        raise ValueError(
            f"Invalid preferred-channel code: {preferred_channel!r}"
        )

    email = row.get("EMAIL_TX", "")

    return {
        "contact_id": row.get("CONT_ID", ""),
        "account_id": row.get("ACCT_ID", ""),
        "first_name": row.get("FRST_NM", ""),
        "last_name": row.get("LAST_NM", ""),
        "email": email if email != "" else None,
        "phone": row.get("PHONE_TX", ""),
        "preferred_channel": _PREFERRED_CHANNELS[preferred_channel],
        "marketing_optout": row.get("OPTOUT_FLG", "") == "Y",
        "owner_id": row.get("OWNER_UID", ""),
        "team_code": row.get("TEAM_CD", ""),
        "created_date": _convert_date(row.get("CREATE_DT", "")),
    }


def convert_all(rows: list[dict]) -> list[dict]:
    """Convert contacts in input order, omitting soft-deleted rows."""
    converted_rows: list[dict] = []

    for row in rows:
        converted = convert_contact(row)
        if converted is not None:
            converted_rows.append(converted)

    return converted_rows
